import numpy as np
from rcb_hb import Session
for label,a in [('saved',np.load('/app/output/trajectory.npz')['actions']),('fast',np.load('/tmp/tail_best_long.npz')['actions'])]:
 s=Session('hurdle',instance='/app/instance.npz');s.reset();m=s.low.model;r0=rf=0;maxx=0
 for t,ac in enumerate(a):
  _,_,done=s.step(ac);d=s.low.data;q=d.qpos;u=1-2*(q[4]**2+q[5]**2);f=np.mean((d.actuator_force/(m.actuator_forcerange[:,1]+1e-6))**2);qual=np.clip((q[2]-.4)/.5,0,1)*np.clip((u-.25)/.75,0,1)*np.exp(-.12*f);sp=np.clip(d.qvel[0]/5,0,1);r0+=qual*sp;rf+=qual*(.03+sp);maxx=max(maxx,q[0]);
  if done:break
 print(label,'steps',t+1,'maxx',maxx,'speedterm',r0,'withfloor',rf,'endz',s.low.data.qpos[2])
